"""Genera código C# a partir de datos (paso Python de la build políglota)."""
import platform
import sys
from pathlib import Path

from packaging.version import Version

destino = Path(sys.argv[1])
version = Version("1.0.0rc1")
codigo = (
    "// <auto-generated/> por tools/gen/gen.py\n"
    "internal static class Datos\n"
    "{\n"
    f'    public const string VersionNormalizada = "{version}";\n'
    f'    public const string GeneradoCon = "python {platform.python_version()}";\n'
    '    public const string Saludo = "¡Construcción políglota en español!";\n'
    "}\n"
)
destino.parent.mkdir(parents=True, exist_ok=True)
# encoding y newline explícitos: en Windows el default de open() es la página
# de códigos del sistema hasta que el modo UTF-8 sea el predeterminado (PEP 686).
destino.write_text(codigo, encoding="utf-8", newline="\n")
print(f"gen: {destino} generado con python {platform.python_version()}")
